"use strict";exports.DEBUG_ENABLED=!0,exports.debugGroup=function(o,n){console.log("▼ "+o);try{n()}finally{console.log("▲ "+o+" 结束")}},exports.debugTable=function(o,n){console.log(o+(n?" (共 "+n.length+" 项)":" (无数据)")),n&&0!==n.length?n.forEach((o,n)=>console.log("  ["+n+"]:",o)):console.log("  (空 - 无任何数据)")},exports.truncate=function(o,n=200){if(null==o)return"(空/缺失)";const e="string"==typeof o?o:String(o);return 0===e.length?"(空字符串)":e.length<=n?e:e.slice(0,n)+"...(总长度: "+e.length+" 字符)"};
